// application.yml:
// storage:
//   upload-dir: /data/upload
//   max-size-mb: 100

@ConfigurationProperties(prefix = "__1__")
@Validated
public class StorageProperties {

    @NotBlank
    private String uploadDir;   // 松散绑定自 upload-dir

    @Min(1)
    private int maxSizeMb;      // 松散绑定自 max-size-mb

    // getter / setter 略
}

// 在配置类上启用该属性 Bean：
@Configuration
@__2__(StorageProperties.class)
public class StorageConfig {
}
